/**
 * REGENERATE THE OUTCOME WITNESS MANIFEST (issue #502).
 *
 *   npm run gen:witnesses
 *
 * `tools/outcome-witnesses.json` is the set of declared outcomes that a
 * deterministic witness in `packages/core/src/events/reach.test.ts` drives
 * through the real slot, decider and commit path. It is generated by running
 * that suite with UPDATE_OUTCOME_WITNESSES=1, never edited by hand: the suite's
 * last test fails on any drift between the two, in either direction.
 *
 * Spawned through `process.execPath` and vitest's own entry rather than `npx`,
 * so there is no shell in the middle and the env var reaches the run the same
 * way on Windows and Linux.
 */
import { spawnSync } from 'node:child_process';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(join(root, 'package.json'));
const vitest = join(dirname(require.resolve('vitest/package.json')), 'vitest.mjs');

const run = spawnSync(
  process.execPath,
  [vitest, 'run', 'packages/core/src/events/reach.test.ts'],
  { cwd: root, stdio: 'inherit', env: { ...process.env, UPDATE_OUTCOME_WITNESSES: '1' } },
);
process.exitCode = run.status ?? 1;
